{"plan_json": "{
  "objectives": [
    {
      "id": 1,
      "objective": "Research why loose/lightly packed aluminium-alloy powder fails to melt into a bath (oxide shells, thermal conductivity, gas entrapment, Mg vs no-Mg differences)",
      "rationale": "Need to understand the fundamental problem before evaluating solutions. The Al2O3/MgO/spinel oxide shell issue is central to why powder doesn't consolidate.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 2,
      "objective": "Research uniaxial compaction of aluminium powder: pressures, relative densities, oxide film breakup, and evidence from remelting compacts, chips, swarf, and foundry alloying tablets",
      "rationale": "Core question - does pressing fix the melting problem? Need quantitative data on pressures, densities, and dissolution behavior.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 3,
      "objective": "Research safety risks of melting compacts (ejection, moisture, gas release, hydrogen pickup) and quality risks (oxide inclusions, nozzle clogging)",
      "rationale": "The equipment maker's warning about ejection needs to be evaluated with evidence.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 4,
      "objective": "Research practical recipes for aluminium powder compaction: pressures, lubricants, sintering, degassing, and pressing parameters for ~19mm compacts",
      "rationale": "Need actionable parameters if compaction is worthwhile.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 5,
      "objective": "Research alternatives: master alloys, fluxes, arc melting, higher superheat, commercial pre-alloyed options for small-batch aluminium alloy preparation",
      "rationale": "Need to compare compaction against other approaches for completeness.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 6,
      "objective": "Synthesize findings into a comprehensive answer with practical recommendations and quick test protocol",
      "rationale": "Final synthesis addressing all 6 sub-questions with citations and numbers.",
      "status": "pending",
      "result": null,
      "evaluation": null
    }
  ]
}"}

